# solve: (array(int64, 2d, C), array(int64, 1d, C)) -> none
atcoder={
    'name': 'numba_modules',
    'file': 'numba_modules.cpython-34m.so',
    'func': ['solve'],
    'gz': b''
}
import gzip, base64
gz = gzip.decompress(base64.b64decode(atcoder['gz']))
with open(atcoder['file'], 'wb') as f:
    f.write(gz)
from numba_modules import solve
