pin = np.fromstring(sys.stdin.buffer.read(), dtype=np.int64, sep=' ')
n = pin[0]
a = pin[1: n + 1]
dp = np.zeros((n, n), dtype=np.int64)
solve(dp, a)
print(dp[0][n - 1])
